 if (select count(*) from reviewed_self_host_qrs) <> 24 then raise exception 'Q/R/S review must contain twenty-four rows'; end if;
 if (select count(*) from reviewed_self_host_qrs r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid and a.slug=r.item->>'slug' where a.published and a.self_hosting_status='self_hostable' and a.name is not distinct from r.item#>>'{current,name}' and lower(a.source_code_url) is not distinct from lower(r.item#>>'{current,source_code_url}') and lower(a.docker_image) is not distinct from lower(r.item#>>'{current,docker_image}')) <> 24 then raise exception 'Q/R/S snapshot changed since review'; end if;
 if exists (select 1 from reviewed_self_host_qrs r cross join lateral jsonb_array_elements_text(r.item#>'{verified,categories}') c(slug) left join public.self_host_app_categories cat on cat.slug=c.slug where cat.id is null) then raise exception 'Q/R/S review contains unknown category'; end if;
end $guard$;
