insert into public.self_host_app_category_links(app_id,category_id) select (r.item->>'app_id')::uuid,c.id from reviewed_self_host_qrs r cross join lateral jsonb_array_elements_text(r.item#>'{verified,categories}') s(slug) join public.self_host_app_categories c on c.slug=s.slug where r.item->>'directory_action'='retain';
insert into public.self_host_app_resource_estimates(app_id,ram_estimate_min_mb,ram_estimate_max_mb,ram_estimate_kind,ram_estimate_confidence,ram_estimate_basis,ram_source_urls,storage_estimate_min_gb,storage_estimate_max_gb,storage_estimate_kind,storage_estimate_confidence,storage_estimate_basis,storage_source_urls,checked_at,updated_at)
select (r.item->>'app_id')::uuid,(r.item#>>'{estimates,ram,min_mb}')::numeric,(r.item#>>'{estimates,ram,max_mb}')::numeric,'estimated',r.item#>>'{estimates,ram,confidence}',r.item#>>'{estimates,ram,basis}',array(select jsonb_array_elements_text(r.item#>'{estimates,ram,source_urls}')),(r.item#>>'{estimates,storage,min_gb}')::numeric,(r.item#>>'{estimates,storage,max_gb}')::numeric,'estimated',r.item#>>'{estimates,storage,confidence}',r.item#>>'{estimates,storage,basis}',array(select jsonb_array_elements_text(r.item#>'{estimates,storage,source_urls}')),now(),now() from reviewed_self_host_qrs r where r.item->>'directory_action'='retain'
on conflict(app_id) do update set ram_estimate_min_mb=excluded.ram_estimate_min_mb,ram_estimate_max_mb=excluded.ram_estimate_max_mb,ram_estimate_kind=excluded.ram_estimate_kind,ram_estimate_confidence=excluded.ram_estimate_confidence,ram_estimate_basis=excluded.ram_estimate_basis,ram_source_urls=excluded.ram_source_urls,storage_estimate_min_gb=excluded.storage_estimate_min_gb,storage_estimate_max_gb=excluded.storage_estimate_max_gb,storage_estimate_kind=excluded.storage_estimate_kind,storage_estimate_confidence=excluded.storage_estimate_confidence,storage_estimate_basis=excluded.storage_estimate_basis,storage_source_urls=excluded.storage_source_urls,checked_at=now(),updated_at=now();
insert into public.self_host_app_install_options(app_id,options,docker_urls,
  docker_images,
  compose_urls,
  truenas_scale_urls,
  unraid_urls,
  umbrel_urls,
  yunohost_urls,
  casaos_urls,
  runtipi_urls,
  cosmos_urls,
  openmediavault_urls,
  synology_urls,
  qnap_urls,
  proxmox_urls,
  home_assistant_os_urls,
  kubernetes_urls,
  helm_urls,
  native_urls,
  binary_urls,
  package_urls,
  other_urls,source_urls,catalog_sources,checked_at,updated_at)
select (r.item->>'app_id')::uuid,coalesce((select jsonb_agg(option||jsonb_build_object('source_url',coalesce(option->>'source_url',option->>'url'),'image',nullif(option->>'image','')) order by coalesce((option->>'sort_order')::integer,0)) from jsonb_array_elements(r.item#>'{verified,install_options}') option),'[]'::jsonb),coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='docker' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select distinct option->>'image' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='docker' and nullif(option->>'image','') is not null order by option->>'image'),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='compose' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='truenas_scale' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='unraid' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='umbrel' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='yunohost' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='casaos' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='runtipi' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='cosmos' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='openmediavault' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='synology' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='qnap' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='proxmox' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='home_assistant_os' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='kubernetes' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='helm' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='native' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='binary' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='package' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),
  coalesce(array(select option->>'url' from jsonb_array_elements(r.item#>'{verified,install_options}') option where option->>'method'='other' order by coalesce((option->>'sort_order')::integer,0)),'{}'::text[]),coalesce(array(select distinct coalesce(nullif(option->>'source_url',''),option->>'url') from jsonb_array_elements(r.item#>'{verified,install_options}') option order by coalesce(nullif(option->>'source_url',''),option->>'url')),'{}'::text[]),'[]'::jsonb,now(),now() from reviewed_self_host_qrs r where r.item->>'directory_action'='retain'
on conflict(app_id) do update set options=excluded.options,docker_urls=excluded.docker_urls,
  docker_images=excluded.docker_images,
  compose_urls=excluded.compose_urls,
  truenas_scale_urls=excluded.truenas_scale_urls,
  unraid_urls=excluded.unraid_urls,
  umbrel_urls=excluded.umbrel_urls,
  yunohost_urls=excluded.yunohost_urls,
  casaos_urls=excluded.casaos_urls,
  runtipi_urls=excluded.runtipi_urls,
  cosmos_urls=excluded.cosmos_urls,
  openmediavault_urls=excluded.openmediavault_urls,
  synology_urls=excluded.synology_urls,
  qnap_urls=excluded.qnap_urls,
  proxmox_urls=excluded.proxmox_urls,
  home_assistant_os_urls=excluded.home_assistant_os_urls,
  kubernetes_urls=excluded.kubernetes_urls,
  helm_urls=excluded.helm_urls,
  native_urls=excluded.native_urls,
  binary_urls=excluded.binary_urls,
  package_urls=excluded.package_urls,
  other_urls=excluded.other_urls,source_urls=excluded.source_urls,catalog_sources='[]'::jsonb,checked_at=now(),updated_at=now();
do $verify$ begin
 if (select count(*) from reviewed_self_host_qrs r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid join public.self_host_app_resource_estimates e on e.app_id=a.id join public.self_host_app_install_options io on io.app_id=a.id where r.item->>'directory_action'='retain' and a.published and a.data_checked_at::date=current_date and e.ram_estimate_kind='estimated' and e.storage_estimate_kind='estimated' and jsonb_array_length(io.options)>0) <> 23 then raise exception 'Q/R/S retained records not fully updated'; end if;
 if (select count(*) from reviewed_self_host_qrs r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid where r.item->>'directory_action' like 'unpublish%' and not a.published) <> 1 then raise exception 'Q/R/S duplicate was not unpublished'; end if;
 if exists (select 1 from reviewed_self_host_qrs r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid where r.item->>'directory_action'='retain' and (a.technical_fact_status#>>'{ram,status}' not in ('published','not_published','unchecked') or a.technical_fact_status#>>'{storage,status}' not in ('published','not_published','unchecked'))) then raise exception 'Q/R/S contains invalid resource status'; end if;
end $verify$;

