do $p_status_guard$ begin
 if (select count(*) from reviewed_self_host_p_status) <> 7 then raise exception 'P status cleanup requires seven retained apps'; end if;
 if (select count(*) from reviewed_self_host_p_status r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid and a.slug=r.item->>'slug' where a.published and a.name is not distinct from r.item#>>'{verified,name}' and lower(a.source_code_url) IS NOT DISTINCT FROM lower(r.item#>>'{verified,source_code_url}') and lower(a.docker_image) IS NOT DISTINCT FROM lower(r.item#>>'{verified,docker_image}')) <> 7 then raise exception 'P records changed before status cleanup'; end if;
end $p_status_guard$;
update public.self_host_apps a set technical_fact_status=coalesce(a.technical_fact_status,'{}'::jsonb)||r.item->'technical_fact_status',updated_at=now() from reviewed_self_host_p_status r where a.id=(r.item->>'app_id')::uuid;
do $p_status_verify$ begin
 if exists (select 1 from reviewed_self_host_p_status r join public.self_host_apps a on a.id=(r.item->>'app_id')::uuid where a.technical_fact_status#>>'{ram,status}' not in ('published','not_published','unchecked') or a.technical_fact_status#>>'{storage,status}' not in ('published','not_published','unchecked')) then raise exception 'P status cleanup found invalid status values'; end if;
end $p_status_verify$;
drop table reviewed_self_host_qrs;commit;
